"""Original vector artwork for the fictional demo catalogue; no external image dependency."""
from pathlib import Path
import random
random.seed(13)
out = Path(__file__).resolve().parents[1] / 'wwwroot' / 'images'
out.mkdir(parents=True, exist_ok=True)
stars = ''.join(f'<circle cx="{random.randrange(600)}" cy="{random.randrange(900)}" r="{random.choice([.5,.7,1,1.4])}" fill="white" opacity="{random.uniform(.15,.7):.2f}"/>' for _ in range(140))
def poster(slug, top, bottom, accent, subtitle, title, scene):
    lines = ''.join(f'<tspan x="300" dy="{0 if i == 0 else 64}">{line}</tspan>' for i,line in enumerate(title))
    svg=f'''<svg xmlns="http://www.w3.org/2000/svg" width="600" height="900" viewBox="0 0 600 900"><defs><linearGradient id="bg" x2=".6" y2="1"><stop stop-color="{top}"/><stop offset="1" stop-color="{bottom}"/></linearGradient><radialGradient id="glow"><stop stop-color="{accent}" stop-opacity=".8"/><stop offset="1" stop-color="{accent}" stop-opacity="0"/></radialGradient><linearGradient id="fade" x2="0" y2="1"><stop stop-color="{bottom}" stop-opacity="0"/><stop offset="1" stop-color="{bottom}"/></linearGradient></defs><rect width="600" height="900" fill="url(#bg)"/>{stars}<circle cx="300" cy="340" r="290" fill="url(#glow)"/>{scene}<rect y="470" width="600" height="430" fill="url(#fade)"/><g text-anchor="middle" font-family="Segoe UI,Arial,sans-serif"><text x="300" y="65" font-size="11" letter-spacing="6" fill="white" opacity=".65">V E G A   P I C T U R E S</text><text x="300" y="615" font-size="12" letter-spacing="3" fill="{accent}">{subtitle}</text><text x="300" y="687" font-size="49" font-weight="800" letter-spacing="-1" fill="#f5eee2">{lines}</text><text x="300" y="835" font-size="10" letter-spacing="3" fill="#ffffff80">MỘT TRẢI NGHIỆM ĐIỆN ẢNH MỚI</text><text x="300" y="867" font-size="8" letter-spacing="4" fill="#ffffff40">VEGA CINEMAS · DEMO ORIGINAL</text></g></svg>'''
    (out/f'{slug}.svg').write_text(svg, encoding='utf-8')
poster('orbit','#0e1830','#070d18','#e8ba7e','VƯỢT QUA MỌI GIỚI HẠN',['QUỸ ĐẠO','CUỐI CÙNG'], '<ellipse cx="330" cy="330" rx="207" ry="60" fill="none" stroke="#e9be85" stroke-width="3" transform="rotate(-25 330 330)"/><circle cx="330" cy="330" r="138" fill="#071121" stroke="#d7ac77" stroke-width="2"/><path d="M90 560Q300 490 600 535V650H0Z" fill="#0b1424"/><g transform="translate(280 435)"><circle cx="0" cy="0" r="14" fill="#ded4bf"/><rect x="-15" y="12" width="30" height="48" rx="7" fill="#a5a395"/><path d="M-10 57L-13 97M10 57L15 97M-17 20L-28 52M17 20L30 48" stroke="#b4b3a4" stroke-width="10"/></g>')
buildings = ''.join(f'<rect x="{i*48}" y="{250+(i*53)%210}" width="38" height="450" fill="{["#122039","#172b40","#253c49"][i%3]}"/>' + ''.join(f'<rect x="{i*48+8}" y="{270+(i*53)%210+j*30}" width="4" height="9" fill="#d7b38a" opacity=".6"/>' for j in range(8)) for i in range(13))
poster('rain','#1e4054','#10192b','#dfb59e','GẶP NHAU GIỮA NHỮNG DỊU DÀNG',['THÀNH PHỐ','SAU CƠN MƯA'],buildings+'<path d="M0 520L250 420L600 520V660H0" fill="#16213a"/><path d="M300 480V545M274 480V543" stroke="#111628" stroke-width="14"/><path d="M250 460Q287 420 327 460Z" fill="#dc8f7c"/><path d="M290 458V490" stroke="#dc8f7c" stroke-width="3"/>')
