trees=''.join(f'<path d="M{x} 70Q{x-70} 300 {x-30} 590H{x+40}Q{x+10} 230 {x+80} 30Z" fill="{color}"/>' for x,color in [(-5,'#0d2832'),(90,'#103a3c'),(550,'#113237'),(450,'#16463e')])
